/* ============================================
   CONTACT CARD
   ============================================ */
.ds-contact-card {
  display: flex;
  align-items: center;
  gap: var(--gap-500);
  padding: var(--padding-500);
  border: 1px solid var(--color-bg-container-border);
  border-radius: var(--radius-300);
  background: var(--color-bg-container-primary-semi);
  text-decoration: none;
  color: inherit;
  transition: background var(--motion-duration-fast) var(--motion-ease-standard), border-color var(--motion-duration-fast) var(--motion-ease-standard);
  /* Resets so the card renders identically whether it's an <a> or a <button>
     (copy-only cards use a button). */
  width: 100%;
  box-sizing: border-box;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.ds-contact-card:hover {
  background: var(--color-bg-container-secondary);
  border-color: var(--color-bg-container-border);
}

.ds-contact-card:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

/* Icon / logo slot */
.ds-contact-card__icon-wrap {
  width: 24px;
  height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.ds-contact-card__icon {
  --icon-size: var(--icon-size-600);
  color: var(--color-text-secondary);
}

.ds-contact-card__logo {
  width: 24px;
  height: 24px;
  object-fit: contain;
}

/* Text */
.ds-contact-card__text {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  min-width: 0;
}

.ds-contact-card__label {
  font-family: var(--font-title-body-family);
  font-size: var(--font-title-body-size);
  font-weight: var(--font-title-body-weight);
  line-height: var(--font-title-body-line-height);
  color: var(--color-text-primary);
}

.ds-contact-card__value {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-tertiary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Actions */
.ds-contact-card__actions {
  display: flex;
  align-items: center;
  gap: var(--gap-100);
  flex-shrink: 0;
}

.ds-contact-card__copy-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  border: none;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--color-text-tertiary);
  cursor: pointer;
  transition: background var(--motion-duration-fast) var(--motion-ease-standard), color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-contact-card__copy-btn:hover {
  background: var(--color-bg-container-tertiary);
  color: var(--color-text-primary);
}

.ds-contact-card__copy-btn:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

.ds-contact-card__copy-btn .material-symbols-rounded {
  --icon-size: var(--icon-size-500);
}

.ds-contact-card__chevron {
  --icon-size: var(--icon-size-500);
  color: var(--color-text-tertiary);
  flex-shrink: 0;
}

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents. */
.ds-contact-card .material-symbols-rounded {
  color: inherit;
}

'use client';

import type React from 'react';
import './ContactCard.css';
import '../../fonts/material-symbols.css';

export interface ContactCardProps {
  /** Primary label — e.g. "Email" */
  label: string;
  /** Visible value or description — e.g. "hello@example.com" */
  value: string;
  /** Link destination */
  href: string;
  /** Icon used when no logo is set — Material Symbol name (string) or custom element (ReactNode) */
  icon?: string | React.ReactNode;
  /** Path to a logo image — preferred over icon when both are provided */
  logo?: string;
  /** Opens link in a new tab and shows open_in_new indicator */
  external?: boolean;
  /** Renders a copy-to-clipboard button; fires onCopy(value) when clicked */
  copyable?: boolean;
  /** Called with the card's value when the copy button is clicked */
  onCopy?: (value: string) => void;
  /** Renders the whole card as a button that copies `value` on click — no navigation */
  copyOnClick?: boolean;
  /** Additional CSS classes */
  className?: string;
}

export const ContactCard = ({
  label,
  value,
  href,
  icon,
  logo,
  external = false,
  copyable = false,
  onCopy,
  copyOnClick = false,
  className = '',
}: ContactCardProps) => {
  const classes = ['ds-contact-card', className].filter(Boolean).join(' ');

  // Protocol links (mailto:, tel:) hand off to the OS default client. Opening
  // them in a new tab leaves an empty blank tab behind, so never set _blank for
  // them — even when `external` is true (it still drives the open_in_new icon).
  const isProtocolLink = /^(mailto:|tel:)/i.test(href);
  const openInNewTab = external && !isProtocolLink;

  const trailingIcon = copyOnClick
    ? 'content_copy'
    : external
      ? 'open_in_new'
      : 'arrow_forward';

  const content = (
    <>
      <span className="ds-contact-card__icon-wrap" aria-hidden="true">
        {logo ? (
          <img
            src={logo}
            alt=""
            width={24}
            height={24}
            className="ds-contact-card__logo"
          />
        ) : typeof icon === 'string' || icon == null ? (
          <span className="material-symbols-rounded ds-contact-card__icon">
            {icon ?? 'link'}
          </span>
        ) : (
          <span className="ds-contact-card__icon">{icon}</span>
        )}
      </span>

      <div className="ds-contact-card__text">
        <span className="ds-contact-card__label">{label}</span>
        <span className="ds-contact-card__value">{value}</span>
      </div>

      <div className="ds-contact-card__actions">
        {copyable && !copyOnClick && (
          <button
            type="button"
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              onCopy?.(value);
            }}
            className="ds-contact-card__copy-btn"
            aria-label={`Copy ${value}`}
          >
            <span className="material-symbols-rounded" aria-hidden="true">
              content_copy
            </span>
          </button>
        )}
        <span className="material-symbols-rounded ds-contact-card__chevron" aria-hidden="true">
          {trailingIcon}
        </span>
      </div>
    </>
  );

  // Copy-only card: the whole card is a button that copies `value` to the
  // clipboard. No navigation at all, so it can't silently fail the way a
  // mailto: link does when there's no registered mail handler.
  if (copyOnClick) {
    return (
      <button
        type="button"
        className={classes}
        onClick={() => onCopy?.(value)}
        aria-label={`Copy ${value} to clipboard`}
      >
        {content}
      </button>
    );
  }

  return (
    <a
      href={href}
      target={openInNewTab ? '_blank' : undefined}
      rel={openInNewTab ? 'noopener noreferrer' : undefined}
      className={classes}
    >
      {content}
    </a>
  );
};
